-- v780 204 variant trames: exact source, title, key and ordinal must agree.
-- Only trame fields change. Canonical truth and all role/private card fields stay unchanged.
WITH edits (scenario_id,variant_id,field,ord,old_title,old_text,new_title,new_text) AS (
 VALUES
('001', 'A', 'v3_runtime_trames', '1', 'CHRONOLOGIE DU PALIER', 'À 02 h 11, Maël appelle l’ami auquel il réclame sa dette. Une silhouette compatible avec cet ami quitte le palier à 02 h 32 ; un visiteur encapuchonné entre dans l’hôtel à 02 h 48. Aucune caméra ne filme l’intérieur de 222.', 'CHRONOLOGIE DU PALIER', 'À 02 h 11, Maël appelle un ami qui lui doit de l’argent. Cet ami semble partir à 02 h 32. Un autre homme arrive à 02 h 48.'),
('001', 'A', 'v3_runtime_trames', '2', 'DETTE ET ENREGISTREMENT', 'Des messages prouvent que l’ancien ami doit de l’argent à Maël. Une captation enregistrée après 02 h 55 contient l’ordre d’effacer quelque chose, puis des bruits de lutte. Les voix ne sont pas identifiables avec certitude.', 'DETTE ET ENREGISTREMENT', 'Des messages confirment la dette de l’ami. Après 02 h 55, un enregistrement capte un ordre d’effacement et une lutte. Les voix restent incertaines.'),
('001', 'A', 'v3_runtime_trames', '3', 'DEUX ALTERCATIONS, UNE LAME', 'Le désordre correspond à deux séquences distinctes : la première avant 02 h 32, la seconde après 02 h 55. Un Opinel ensanglanté et essuyé est retrouvé dans une benne de service. Ces constatations ne prouvent pas qui le portait au moment du coup.', 'DEUX ALTERCATIONS, UNE LAME', 'Deux altercations ont eu lieu. Un couteau ensanglanté est retrouvé dans une benne, mais on ignore qui l’a utilisé.'),
('001', 'B', 'v3_runtime_trames', '1', 'LA DISPUTE ET LE VISITEUR', 'Maël appelle son ancien ami à 02 h 11. Une silhouette compatible avec lui quitte l’étage à 02 h 32, avant l’entrée d’un visiteur encapuchonné à 02 h 48. Des bruits de dispute précèdent le départ et un choc retentit vers 03 h 05.', 'LA DISPUTE ET LE VISITEUR', 'Maël se dispute avec son ami avant 02 h 32. Un visiteur arrive à 02 h 48. Un choc est entendu à 03 h 05.'),
('001', 'B', 'v3_runtime_trames', '2', 'UNE BLESSURE PLUS ANCIENNE', 'Les traces de saignement et l’examen de la plaie sont compatibles avec une blessure infligée au cours de la première dispute. Maël peut encore parler quelque temps après avoir été blessé. L’expertise ne fournit pas d’heure exacte.', 'UNE BLESSURE PLUS ANCIENNE', 'La blessure de Maël pourrait venir de la première dispute. Il a pu parler ensuite. L’heure exacte reste inconnue.'),
('001', 'B', 'v3_runtime_trames', '3', 'LE DERNIER CHOC N’ÉTAIT PAS UN COUP', 'Le choc de 03:05 correspond aux traces d''un meuble renversé. La blessure par lame précède la seconde visite. L''Opinel ne fournit aucune preuve de manipulation par le second visiteur ; celui-ci n''a pas alerté les secours.', 'BRUIT DU MEUBLE', 'Le bruit de 03 h 05 vient d’un meuble. Maël était déjà blessé avant le second visiteur, qui n’a pas appelé les secours.'),
('001', 'C', 'v3_runtime_trames', '1', 'DEUX DISPUTES DANS LA MÊME NUIT', 'Maël appelle son ancien ami à 02 h 11. Celui-ci semble quitter le palier à 02 h 32, tandis qu’un visiteur encapuchonné entre à 02 h 48. Une agitation beaucoup plus forte retentit vers 03 h 05 ; personne ne voit ce qui se produit dans 222.', 'DEUX DISPUTES DANS LA MÊME NUIT', 'L’ami de Maël part vers 02 h 32. Un visiteur arrive à 02 h 48. Vers 03 h 05, une agitation éclate dans la chambre.'),
('001', 'C', 'v3_runtime_trames', '2', 'UNE TROISIÈME PRÉSENCE POSSIBLE', 'Une trace sur la poignée intérieure est compatible avec le passage d’un troisième intervenant lors de la lutte tardive. Une marque de préhension est observée sur la manche de Maël. Ces indices ne désignent pas avec certitude la personne entrée dans 222.', 'UNE TROISIÈME PRÉSENCE POSSIBLE', 'Une trace sur la poignée et une marque sur la manche de Maël suggèrent une troisième présence. Rien ne l’identifie.'),
('001', 'C', 'v3_runtime_trames', '3', 'LA TRAJECTOIRE NE DIT PAS L’INTENTION', 'La plaie est compatible avec un mouvement brusque du poignet tenant le couteau pendant la lutte. Ce mécanisme peut être accidentel, mais seule la confrontation des versions permet d’en examiner la cause. Provoquer la blessure ne démontre pas l’intention de tuer.', 'LA TRAJECTOIRE NE DIT PAS L’INTENTION', 'La blessure a pu venir d’un geste brusque pendant la lutte. Elle ne prouve pas une volonté de tuer.'),
('002', 'A', 'v200_runtime_trames', '1', 'LA CONFIDENCE PUBLIÉE', 'À 20 h 51, une nouvelle publication reprend des propos que Léon avait confiés en privé. Son auteur est identifié. Le nombre de partages ne permet pas de mesurer son effet sur Léon.', 'LA CONFIDENCE PUBLIÉE', 'À 20 h 51, quelqu’un publie une confidence privée de Léon. L’auteur est connu, pas l’effet exact sur Léon.'),
('002', 'A', 'v200_runtime_trames', '2', 'CE QUI S’EST RÉPÉTÉ', 'Les archives montrent que la publication de 20 h 51 n’était pas la première. Les humiliations sont réparties sur plusieurs semaines. Les messages hostiles de l''autre proche appartiennent à un conflit distinct.', 'CE QUI S’EST RÉPÉTÉ', 'Les humiliations contre Léon duraient depuis des semaines. Les messages d’un autre proche relèvent d’un conflit distinct.'),
('002', 'A', 'v200_runtime_trames', '3', 'QUATRE CONDUITES, PAS UNE CAUSE UNIQUE', 'Les heures établissent des actes distincts : humiliation répétée, messages violents, pleurs entendus sans intervention et dernier départ du meilleur ami. Ces faits sont documentés ; aucun ne permet d''attribuer à lui seul la mort de Léon.', 'QUATRE CONDUITES, PAS UNE CAUSE UNIQUE', 'Léon a subi des humiliations, des messages violents et des refus d’aide. Aucun fait ne suffit seul à expliquer sa mort.'),
('002', 'B', 'v200_runtime_trames', '1', 'LE MESSAGE D’ALERTE', 'À 22 h 16, Léon écrit à son meilleur ami qu''il traverse une crise et lui demande de contacter une aide extérieure. La réception du message est confirmée, sans que l''on sache encore comment il a réagi.', 'LE MESSAGE D’ALERTE', 'À 22 h 16, Léon demande à son meilleur ami d’appeler de l’aide. Le message a été reçu.'),
('002', 'B', 'v200_runtime_trames', '2', 'L’AIDE RESTÉE SUR LE PAPIER', 'À 22 h 23, le meilleur ami rédige une note pour contacter une aide extérieure. Aucun appel correspondant n''est enregistré ensuite. Les pleurs entendus par le voisin ne prouvent pas qu''il connaissait la teneur de l''alerte.', 'L’AIDE RESTÉE SUR LE PAPIER', 'À 22 h 23, son meilleur ami écrit qu’il faut appeler de l’aide. Aucun appel correspondant n’apparaît ensuite.'),
('002', 'B', 'v200_runtime_trames', '3', 'LE DÉLAI ET LES INFORMATIONS', 'L''alerte a été reçue. Le besoin d''aide a été compris : la note le confirme. L''appel n''a pas été passé. Les humiliations antérieures et les messages cruels restent des faits séparés. Rien ne permet d''affirmer qu''une aide aurait certainement empêché le décès.', 'LE DÉLAI ET LES INFORMATIONS', 'Le meilleur ami a compris la demande d’aide, mais n’a pas appelé. On ignore si les secours auraient évité la mort.'),
('002', 'C', 'v200_runtime_trames', '1', 'UNE CONFIDENCE DIFFUSÉE', 'Léon découvre qu''une confidence privée circule. Plus tard, un conflit avec son ancien colocataire se termine par des paroles dures. Ces épisodes ne prouvent pas une intention collective.', 'UNE CONFIDENCE DIFFUSÉE', 'Une confidence de Léon a été diffusée. Il se dispute ensuite avec son ancien colocataire. Rien ne prouve une action commune.'),
('002', 'C', 'v200_runtime_trames', '2', 'UNE EXCUSE SANS ACCUSÉ DE LECTURE', 'À 21:58, L’ancien ami envoie des excuses sans confirmation de lecture. Le voisin entend ensuite des pleurs et lit à 22:12 une demande de prévenir un ami, sans la transmettre.', 'UNE EXCUSE SANS ACCUSÉ DE LECTURE', 'À 21 h 58, un ancien ami s’excuse sans preuve de lecture. À 22 h 12, le voisin lit un message demandant de prévenir un proche, mais ne le transmet pas.'),
('002', 'C', 'v200_runtime_trames', '3', 'PERSONNE N’AVAIT LA MÊME HISTOIRE', 'Le voisin a lu une demande personnelle de prévenir un proche et n''a rien transmis. Le meilleur ami, ignorant ce message, est venu de sa propre initiative puis est reparti. Aucune cause unique du décès ne peut être déduite.', 'PERSONNE N’AVAIT LA MÊME HISTOIRE', 'Le voisin ne transmet pas la demande de Léon. Le meilleur ami, qui l’ignorait, vient puis repart.'),
('003', 'A', 'v220_runtime_trames', '1', 'LE DOSSIER ORIGINAL', 'Le dossier scientifique signalait le danger avant les décisions. La question est désormais de savoir qui l''avait réellement lu.', 'LE DOSSIER ORIGINAL', 'Un dossier scientifique signalait un danger avant les décisions. On ignore encore qui l’avait lu.'),
('003', 'A', 'v220_runtime_trames', '2', 'DEUX COPIES DIFFÉRENTES', 'L''avertissement figure dans le dossier d''Helios, mais pas dans la copie reçue par le gouvernement avant le départ.', 'DEUX COPIES DIFFÉRENTES', 'L’avertissement figure dans les archives d’Helios, mais pas dans la copie envoyée au gouvernement.'),
('003', 'A', 'v220_runtime_trames', '3', 'TROIS DÉCISIONS DISTINCTES', 'S1 a maintenu les opérations, S2 a autorisé le transport malgré l''avertissement et S3 a supprimé celui-ci de la copie gouvernementale.', 'TROIS DÉCISIONS DISTINCTES', 'Les documents séparent trois décisions : poursuivre, autoriser le transport et retirer l’avertissement.'),
('003', 'B', 'v211_runtime_trames', '1', 'Deux documents incompatibles', 'Le service des validations reçoit à 08 h 24 deux constats contradictoires. Une décision de conformité ne peut pas les réconcilier à elle seule.', 'Deux documents incompatibles', 'À 08 h 24, le service des validations reçoit deux rapports qui se contredisent.'),
('003', 'B', 'v211_runtime_trames', '2', 'Le statut « conforme »', 'À 08 h 47, le registre est clos sans justification de la contradiction. Le directeur consulte ensuite cette validation, et non les annotations internes.', 'Le statut « conforme »', 'À 08 h 47, le registre est déclaré conforme sans résoudre la contradiction. Le directeur ne voit que cette validation.'),
('003', 'B', 'v211_runtime_trames', '3', 'La décision a précédé l''explication', 'Le service a marqué le dossier conforme avant d''avoir expliqué l''écart. Le directeur s''est fondé sur cette validation et le contrôleur n''a pas obtenu la correction demandée. Rien ne prouve une fraude intentionnelle.', 'La décision a précédé l''explication', 'Le dossier a été déclaré conforme avant la correction des contradictions. Rien ne prouve une fraude volontaire.'),
('003', 'B', 'v220_runtime_trames', '1', 'LE DOSSIER ÉTAIT SIGNÉ', 'Le dossier signé par S2 permet la poursuite. L''enquête doit établir les informations connues avant cette signature.', 'LE DOSSIER ÉTAIT SIGNÉ', 'Un dossier signé autorise la poursuite. On ignore encore ce que son signataire savait.'),
('003', 'B', 'v220_runtime_trames', '2', 'S2 AVAIT LU LE DANGER', 'S2 a lu l''avertissement avant de signer. S1 n''a reçu que le dossier qui affirmait que tout était en ordre.', 'AVERTISSEMENT CONNU', 'Le signataire connaissait l’avertissement. Le directeur n’avait reçu qu’une copie disant que tout allait bien.'),
('003', 'B', 'v220_runtime_trames', '3', 'LE MENSONGE, PUIS LE SILENCE', 'S2 a signé sciemment un dossier faux. S3 a caché ensuite le danger découvert avant le départ. Les deux décisions sont distinctes.', 'LE MENSONGE, PUIS LE SILENCE', 'Un dossier faux a été signé. L’avertissement a été caché ensuite, par une autre personne.'),
('003', 'C', 'v220_runtime_trames', '1', 'UN ACCORD ANNONCÉ', 'Le dossier affirme que l''équipe destinataire avait accepté le transport. L''enquête cherche à retrouver cet accord.', 'UN ACCORD ANNONCÉ', 'Le dossier affirme que l’équipe destinataire avait accepté le transport. Cet accord reste introuvable.'),
('003', 'C', 'v220_runtime_trames', '2', 'LE TRANSPORT POUVAIT ENCORE ÊTRE ARRÊTÉ', 'L''équipe destinataire affirme n''avoir rien accepté. Un avertissement reçu avant le départ devait entraîner son arrêt.', 'LE TRANSPORT POUVAIT ENCORE ÊTRE ARRÊTÉ', 'L’équipe destinataire dit n’avoir jamais accepté le transport. Un avertissement aurait dû l’arrêter.'),
('003', 'C', 'v220_runtime_trames', '3', 'S3 A CACHÉ LE DERNIER AVERTISSEMENT', 'S1 a menacé S2, S2 a inventé l''accord et S3 a retiré l''avertissement qui aurait permis à la sécurité d''arrêter le transport.', 'AVERTISSEMENT RETIRÉ', 'Des échanges montrent une menace, un faux accord et un avertissement retiré. Ces actes ont précédé le transport.'),
('004', 'A', 'v230_runtime_trames', '1', 'APPEL REÇU', 'Le journal confirme un appel de Sofia à l''ex-partenaire avant tous les autres échanges. Son contenu n''est pas publié à ce stade.', 'APPEL À L’EX-PARTENAIRE', 'Le téléphone de Sofia confirme qu’elle a appelé son ex-partenaire avant les autres échanges. On ignore ce qu’ils se sont dit.'),
('004', 'A', 'v230_runtime_trames', '2', 'TROIS NIVEAUX D''INFORMATION', 'Le message reçu par l''ami est moins explicite que le témoignage sur le premier appel. Aucun échange ne confirme qu''un relais était organisé.', 'MESSAGES DIFFÉRENTS', 'Sofia envoie à son ami un message moins alarmant que son premier appel. Rien ne montre qu’un proche devait prévenir l’autre.'),
('004', 'A', 'v230_runtime_trames', '3', 'LA QUESTION NON ENVOYÉE', 'Une question non expédiée apparaît dans le téléphone de l''ami. La trace du passage dans la rue ne comporte aucun avis transmis au proche. L''enquête doit établir ce que chacun pouvait savoir, sans inférer une issue médicale certaine.', 'QUESTION NON ENVOYÉE', 'L’ami de Sofia a rédigé une question sans l’envoyer. Aucun message ne montre que le proche passé dans la rue avait été prévenu.'),
('004', 'B', 'v230_runtime_trames', '1', 'DEUX ALERTES DISTINCTES', 'Deux messages adressés à des destinataires différents arrivent après la rupture du premier suspect. Le contenu exact de leur conversation n''est pas encore connu.', 'DEUX MESSAGES DIFFÉRENTS', 'Après une dispute avec son ex-partenaire, Sofia envoie deux messages différents : un à son ami proche, l’autre au proche du quartier.'),
('004', 'B', 'v230_runtime_trames', '2', 'L''APPEL ENTRE PROCHES', 'Le journal prouve une conversation entre les deux destinataires des alertes. Aucune trace de contact avec Sofia ou un service d''aide ne suit cet échange.', 'APPEL ENTRE LES PROCHES', 'L’ami proche de Sofia et le proche du quartier se sont appelés après ses messages. Aucun appel aux secours n’apparaît ensuite.'),
('004', 'B', 'v230_runtime_trames', '3', 'UN RELAIS SANS ACCORD', 'La comparaison des messages et des témoignages ne permet d''identifier aucune attribution explicite de la prise en charge. Les deux proches connaissaient l''inquiétude de l''autre. L''enquête doit déterminer la part de chacun.', 'PERSONNE NE SE CHARGE DES SECOURS', 'Les messages ne disent pas si l’ami proche de Sofia ou le proche du quartier devait venir l’aider ou appeler les secours.'),
('004', 'C', 'v230_runtime_trames', '1', 'LE PREMIER TÉMOIN', 'Un proche est aperçu dans la rue et nie d''abord sa présence. La seule présence ne permet pas encore d''établir ce qu''il savait.', 'PRÉSENCE DANS LA RUE', 'Le proche de Sofia qui habite le quartier est vu dans la rue. Il avait d’abord nié être passé. On ignore ce qu’il savait.'),
('004', 'C', 'v230_runtime_trames', '2', 'UN DÉCALAGE ENTRE LES HEURES', 'Les journaux montrent que l''appel à l''ex-partenaire et le message à l''ami précèdent le passage rapporté. Aucun relais au troisième proche n''est documenté.', 'MESSAGES AVANT LE PASSAGE', 'Sofia a appelé son ex-partenaire et écrit à son ami avant le passage du proche du quartier. Rien ne montre qu’il avait été prévenu.'),
('004', 'C', 'v230_runtime_trames', '3', 'LA RUMEUR N''ÉTAIT PAS UNE ALERTE', 'L''horodatage du passage est authentifié mais postérieur aux messages. La rumeur inverse cet ordre. Le silence du troisième proche sur sa présence n''efface pas les choix antérieurs des deux premiers.', 'LA CAMÉRA CONTREDIT LA RUMEUR', 'La caméra situe le passage du proche du quartier après les messages. Une rumeur disait l’inverse. Les deux autres proches avaient reçu leurs alertes avant.'),
('005', 'A', 'v250_runtime_trames', '1', 'L''agence savait', 'Des documents montrent que Keller avait été alerté de la détresse de Mara. Sa mort a laissé des proches en colère.', 'L''agence savait', 'Des documents montrent que Keller connaissait la détresse de Mara. Sa mort a laissé ses proches en colère.'),
('005', 'A', 'v250_runtime_trames', '2', 'Trois déplacements', 'Une vidéo et un badge situent deux suspects ailleurs. Une troisième visite commence quelques minutes avant la mort.', 'Trois déplacements', 'Une caméra et un badge placent deux suspects ailleurs. Une troisième visite commence peu avant la mort de Keller.'),
('005', 'A', 'v250_runtime_trames', '3', 'La copie laissée au sol', 'Le masque a servi pendant la confrontation puis a été posé près du corps, avec des portraits abîmés. La scène ne prouve pas le retour du tueur original.', 'La copie laissée au sol', 'Le masque est utilisé pendant la dispute, puis posé près du corps. Cela ne prouve pas le retour de l’ancien tueur.'),
('005', 'B', 'v250_runtime_trames', '1', 'Le sourire du gala', 'Keller affiche publiquement le respect des mannequins, mais une dispute éclate juste avant l''ouverture de la soirée.', 'Le sourire du gala', 'Au gala, Keller se présente comme respectueux. Une dispute éclate pourtant avant le début de la soirée.'),
('005', 'B', 'v250_runtime_trames', '2', 'Le salon privé', 'Une ouverture du salon est enregistrée à 21 h 09. Le discours sur scène se poursuit pendant la mort.', 'Le salon privé', 'Le salon privé est ouvert à 21 h 09 pendant que le discours continue ailleurs.'),
('005', 'B', 'v250_runtime_trames', '3', 'Un masque venu de l''extérieur', 'Le masque a été apporté et porté par le meurtrier, puis laissé dans le salon. Le dossier de Mara n''est pris qu''après sa mort.', 'Un masque venu de l''extérieur', 'Le meurtrier a apporté et porté le masque. Le dossier de Mara a été pris après la mort de Keller.'),
('005', 'C', 'v250_runtime_trames', '1', 'Une visite masquée', 'Une personne masquée est signalée avant la mort de Keller. Cela ne suffit pas à identifier l''auteur des coups.', 'Une visite masquée', 'Une personne masquée est vue avant la mort de Keller. Rien ne prouve que c’est elle qui l’a frappé.'),
('005', 'C', 'v250_runtime_trames', '2', 'Deux portes', 'La sortie de l''ouest et l''entrée de l''est se produisent vers 20 h 57, dans des couloirs séparés.', 'Deux portes', 'Une personne sort à l’ouest et une autre entre à l’est vers 20 h 57.'),
('005', 'C', 'v250_runtime_trames', '3', 'Trois actes', 'Les heures distinguent une menace, une lutte mortelle et un déplacement du masque. Les documents manquants ajoutent une dernière piste.', 'Trois actes', 'Les heures montrent une menace, une lutte mortelle puis le déplacement du masque. Des documents manquent encore.'),
('006', 'A', 'v260_runtime_trames', '1', 'UNE SORTIE ORDINAIRE', 'Les quatre amis ont été photographiés au belvédère et leur appel aux secours depuis le chalet a été enregistré.', 'UNE SORTIE ORDINAIRE', 'Une photo montre les quatre amis au belvédère. Leur appel aux secours depuis le chalet est enregistré.'),
('006', 'A', 'v260_runtime_trames', '2', 'LE DÉFI CACHÉ', 'La vidéo montre une provocation ciblée contre Noé. Mathis était intervenu avant la chute.', 'LE DÉFI CACHÉ', 'Une vidéo montre que Noé a été provoqué. Mathis est intervenu avant la chute.'),
('006', 'A', 'v260_runtime_trames', '3', 'LES DERNIÈRES SECONDES', 'La confrontation des pièces et des positions permet de distinguer le dernier geste du mensonge partagé.', 'DERNIER GESTE CONTESTÉ', 'Les traces du dernier geste et la version donnée par les trois amis ne racontent pas la même chose.'),
('006', 'B', 'v260_runtime_trames', '1', 'UNE SORTIE ORDINAIRE', 'Les quatre amis ont été photographiés au belvédère et leur appel aux secours depuis le chalet a été enregistré.', 'UNE SORTIE ORDINAIRE', 'Une photo montre les quatre amis au belvédère. Leur appel aux secours depuis le chalet est enregistré.'),
('006', 'B', 'v260_runtime_trames', '2', 'LE DÉFI CACHÉ', 'La vidéo montre une provocation ciblée contre Noé. Mathis était intervenu avant la chute.', 'LE DÉFI CACHÉ', 'Une vidéo montre que Noé a été provoqué. Mathis est intervenu avant la chute.'),
('006', 'B', 'v260_runtime_trames', '3', 'LES DERNIÈRES SECONDES', 'La confrontation des pièces et des positions permet de distinguer le dernier geste du mensonge partagé.', 'DERNIER GESTE CONTESTÉ', 'Les traces du dernier geste et la version donnée par les trois amis ne racontent pas la même chose.'),
('006', 'C', 'v260_runtime_trames', '1', 'UNE SORTIE ORDINAIRE', 'Les quatre amis ont été photographiés au belvédère et leur appel aux secours depuis le chalet a été enregistré.', 'UNE SORTIE ORDINAIRE', 'Une photo montre les quatre amis au belvédère. Leur appel aux secours depuis le chalet est enregistré.'),
('006', 'C', 'v260_runtime_trames', '2', 'LE DÉFI CACHÉ', 'La vidéo montre une provocation ciblée contre Noé. Mathis était intervenu avant la chute.', 'LE DÉFI CACHÉ', 'Une vidéo montre que Noé a été provoqué. Mathis est intervenu avant la chute.'),
('006', 'C', 'v260_runtime_trames', '3', 'LES DERNIÈRES SECONDES', 'La confrontation des pièces et des positions permet de distinguer le dernier geste du mensonge partagé.', 'DERNIER GESTE CONTESTÉ', 'Les traces du dernier geste et la version donnée par les trois amis ne racontent pas la même chose.'),
('007', 'A', 'v280_runtime_trames', '1', 'UN TESTAMENT AVANT LA MORT', 'Le testament porte une signature authentique obtenue sous pression. Une dette privée constitue un autre mobile, sans que ces documents situent quiconque pendant la chute.', 'UN TESTAMENT AVANT LA MORT', 'Le testament est authentique mais signé sous pression. Une dette existe aussi. Ces pièces ne situent personne lors de la chute.'),
('007', 'A', 'v280_runtime_trames', '2', 'LA PIÈCE RETIRÉE', 'Une lettre de 2013 sur les comptes d''une ancienne vente a disparu du dossier familial. Un rendez-vous privé autour de cette pièce a été fixé après les départs des deux autres proches.', 'LA PIÈCE RETIRÉE', 'Une lettre de 2013 sur une ancienne vente a disparu. Un rendez-vous secret était prévu après le départ des autres proches.'),
('007', 'A', 'v280_runtime_trames', '3', 'DEUX ENTRETIENS, UNE SEULE CHUTE', 'La lettre a été déchirée à proximité du seuil de l''escalier ; des traces d''encre et des horaires situent un contact possible pendant la dispute. La scène ne révèle pas à elle seule qui a fait perdre l''équilibre au défunt, ni avec quelle intention.', 'DEUX ENTRETIENS, UNE SEULE CHUTE', 'Une lettre déchirée est trouvée près de l’escalier. Les traces ne prouvent pas qui a fait tomber la victime.'),
('007', 'B', 'v280_runtime_trames', '1', 'L''ULTIMATUM PRÉCÈDE LA LUTTE', 'La signature authentique a été obtenue sous pression. Les relevés de sortie situent le bénéficiaire ailleurs pendant qu''un document de dette devient l''objet d''un rendez-vous.', 'L''ULTIMATUM PRÉCÈDE LA LUTTE', 'La signature est vraie, mais obtenue sous pression. Le bénéficiaire était ailleurs lors du rendez-vous sur la dette.'),
('007', 'B', 'v280_runtime_trames', '2', 'UNE PIÈCE CHANGE DE PLACE', 'Une rencontre privée concerne les justificatifs d''une dette, pas une nouvelle modification du testament. La chemise financière est ensuite photographiée dans la pièce où se trouve le défunt.', 'UNE PIÈCE CHANGE DE PLACE', 'Une rencontre portait sur une dette, pas sur le testament. Les documents ont ensuite été photographiés près du défunt.'),
('007', 'B', 'v280_runtime_trames', '3', 'LE RENDEZ-VOUS SUR LA DETTE', 'Le dossier apparaît sur une photographie postérieure à la chute, avant de disparaître de l''inventaire. Des traces sur les vêtements et les horaires permettent de distinguer le contact au palier de la dissimulation ultérieure, sans déduire l''intention du seul retrait.', 'LE RENDEZ-VOUS SUR LA DETTE', 'Le dossier financier apparaît sur une photo après la chute, puis disparaît. Cela ne prouve pas une intention de tuer.'),
('007', 'C', 'v280_runtime_trames', '1', 'LA COPIE QUI DÉRANGE', 'Une copie datée révèle un lien de filiation absent du projet de testament. La provenance du duplicata est identifiable, mais sa valeur successorale reste à apprécier. Cette découverte donne un motif à plusieurs proches ; elle ne permet d’imputer ni la lutte ni la chute.', 'LA COPIE QUI DÉRANGE', 'Une copie révèle un lien de parenté absent du testament. Plusieurs proches ont un intérêt, sans preuve sur la chute.'),
('007', 'C', 'v280_runtime_trames', '2', 'DEUX RENDEZ-VOUS DISTINCTS', 'Le registre de sortie place le bénéficiaire hors de la propriété dès 17 h 06. À 17 h 35, une demande de rencontre concerne l’original de l’attestation et non le projet de testament. La liste d’accès établit une présence tardive, pas encore le geste à l’origine du décès.', 'DEUX RENDEZ-VOUS DISTINCTS', 'Le bénéficiaire est parti à 17 h 06. À 17 h 35, une rencontre est demandée pour une attestation, pas pour le testament.'),
('007', 'C', 'v280_runtime_trames', '3', 'L’ENVELOPPE ET LA CHUTE', 'À l''issue du dernier entretien, l''enveloppe de l''attestation est abîmée. Des traces sur le poignet du défunt et une manche déchirée appellent une comparaison, mais aucune trace isolée ne montre comment l''équilibre a été perdu. La pression financière et le mensonge sur la filiation restent des questions distinctes.', 'L’ENVELOPPE ET LA CHUTE', 'Une enveloppe abîmée et des marques sur les vêtements montrent un contact, sans prouver comment la victime est tombée.'),
('008', 'A', 'v300_runtime_trames', '1', 'LE REGISTRE NE MENT PAS SEUL', 'Le registre original de la salle des archives fixe un retrait autorisé du dossier D-14 à 18 h 12. Le premier témoin a déclaré un contrôle continu jusqu’à 18 h 24, alors que son écriture a été ajoutée après l’audience préparatoire. Le décalage établit une version inexacte, pas l’auteur d’un détournement.', 'LE REGISTRE NE MENT PAS SEUL', 'D-14 est sorti à 18 h 12. Un témoin dit pourtant avoir surveillé la salle jusqu’à 18 h 24.'),
('008', 'A', 'v300_runtime_trames', '2', 'UNE DÉPOSITION PRÉPARÉE', 'Un message horodaté, conservé par le système de préparation des dépositions, demande de ne pas évoquer un intervalle sans contrôle. L''authenticité de l''échange est documentée; il faut encore relier son origine, son destinataire et son contexte avant d''imputer une influence précise. Le troisième témoin ne figure pas parmi les destinataires.', 'UNE DÉPOSITION PRÉPARÉE', 'Un message demandait de taire un trou de surveillance. Le troisième témoin ne l’a pas reçu.'),
('008', 'A', 'v300_runtime_trames', '3', 'UN MENSONGE, UN FAIT VRAI', 'Un enregistrement de la porte et le registre initial situent la sortie de D-14 à 18 h 12. Les pièces ne prouvent aucune altération. Le troisième témoin a faussé son heure d''arrivée pour une raison personnelle; le premier a masqué une négligence et le deuxième a fait pression sur une déposition. Il reste à qualifier séparément ces comportements.', 'UN MENSONGE, UN FAIT VRAI', 'D-14 est sorti à 18 h 12 sans trace d’altération. Les témoins ont menti sur des faits différents.'),
('008', 'B', 'v300_runtime_trames', '1', 'LE SCELLÉ SANS GARDE', 'La feuille de prise en charge du dossier D-14 prévoit une garde continue. Entre 18 h 05 et 18 h 18, aucune signature de relais ni surveillance n’est attestée. Le premier témoin affirme pourtant avoir surveillé la pièce durant tout ce créneau.', 'LE SCELLÉ SANS GARDE', 'D-14 n’a pas été surveillé entre 18 h 05 et 18 h 18. Un témoin affirme pourtant le contraire.'),
('008', 'B', 'v300_runtime_trames', '2', 'CORRIGÉ APRÈS L’INCIDENT', 'Une ligne du registre présente une surveillance continue, mais le système situe sa saisie réelle à 18 h 41, après l''intervalle de 18 h 05 à 18 h 18. Un échange préparatoire évoque aussi le silence à garder sur ce créneau. Les comptes de saisie et les destinataires doivent être recoupés pour distinguer l''auteur de la défaillance et celui qui a cherché à la cacher lors de l''audition.', 'CORRIGÉ APRÈS L’INCIDENT', 'Une ligne de surveillance continue a été ajoutée à 18 h 41, après le créneau sans garde.'),
('008', 'B', 'v300_runtime_trames', '3', 'LA FAILLE, PAS LA ROMANCE', 'La pièce D-14 n''a pas disparu et le contrôle ne révèle pas d''altération identifiable. Pourtant, entre 18 h 05 et 18 h 18, aucune garde valide n''était assurée. La caméra situe le troisième témoin au vestibule pendant l''intervalle; l''absence de surveillance et les consignes de silence doivent être évaluées séparément.', 'DOSSIER INTACT, GARDE ABSENTE', 'D-14 est intact, mais personne ne le surveillait entre 18 h 05 et 18 h 18. Un témoin était au vestibule.'),
('008', 'C', 'v300_runtime_trames', '1', 'UN DÉTAIL IMPOSSIBLE À DEVINER', 'Le troisième témoin décrit la pliure et la marque d’inventaire au dos de D-14, détails absents de la version remise aux témoins. Il affirme pourtant n’avoir jamais manipulé ni revu cette pièce. Cette connaissance exige une explication ; elle ne démontre pas encore le déplacement.', 'UN DÉTAIL IMPOSSIBLE À DEVINER', 'Un témoin décrit une marque cachée au dos de D-14, mais affirme ne jamais avoir revu cette pièce.'),
('008', 'C', 'v300_runtime_trames', '2', 'LE SECOND PASSAGE', 'Un badge temporaire apparaît dans les journaux entre 18 h 12 et 18 h 21, après une première visite privée à 17 h 40. Cette autorisation donnait accès au couloir, pas à l''ouverture de D-14. Le second passage doit être rapproché des inventaires et des témoignages; les journaux ne montrent pas le geste matériel ni ses raisons.', 'LE SECOND PASSAGE', 'Un badge temporaire passe entre 18 h 12 et 18 h 21. Il permet l’accès au couloir, pas au dossier D-14.'),
('008', 'C', 'v300_runtime_trames', '3', 'LE DOCUMENT A CHANGÉ DE PLACE', 'Deux inventaires établissent que D-14 a changé de casier et que sa bande de scellement a été déchirée. L''accès non expliqué de 18 h 12, les détails du verso connus d''un témoin et les fibres du rabat donnent des pistes convergentes. La confrontation finale doit distinguer celui qui a effectivement touché la pièce de ceux qui ont seulement menti sur d''autres faits.', 'LE DOCUMENT A CHANGÉ DE PLACE', 'D-14 a changé de casier et son scellé est déchiré. Les traces ne disent pas qui l’a déplacé.'),
('009', 'A', 'v330_runtime_trames', '1', 'LE REFUS N''EST PAS UNE HÉSITATION', 'À 09 h 14, le Sujet 17 indique sans ambiguïté qu''il retire son consentement et demande la fin du protocole. L''enregistrement horodaté et un reçu de transcription authentifié concordent. Un entretien ultérieur n''a pas effacé ce retrait.', 'LE REFUS N''EST PAS UNE HÉSITATION', 'À 09 h 14, le Sujet 17 retire clairement son accord. Son refus est enregistré.'),
('009', 'A', 'v330_runtime_trames', '2', 'RÉCEPTION, VALIDATION, EXÉCUTION', 'L’alerte transmise à 09 h 19 est reçue dans le circuit institutionnel à 09 h 22. Une instruction concernant la continuation d’ORPHÉE circule ensuite. Les accusés de réception, les habilitations et les actes cliniques ne répondent pas à la même question : qui a reçu, qui a validé et qui a exécuté ?', 'RÉCEPTION, VALIDATION, EXÉCUTION', 'Une alerte part à 09 h 19 et est reçue à 09 h 22. Une consigne de continuer circule ensuite.'),
('009', 'A', 'v330_runtime_trames', '3', 'UNE MÉMOIRE PERDUE N''EFFACE PAS UNE CONSIGNE', 'Le Sujet 17 manifeste une détresse à 09 h 40, et les exercices cessent à 09 h 42. Le médecin tombe à 09 h 47 en se dirigeant vers le poste de secours. Les évaluations ultérieures sont compatibles avec une atteinte authentique de mémoire récente, mais les journaux antérieurs confirment qu''il avait reçu une consigne institutionnelle de poursuite et exécuté une étape sans nouveau consentement. Il reste à distinguer celui qui a ordonné et celui qui a appliqué.', 'HORAIRES AVANT LA CHUTE', 'Après une détresse à 09 h 40, les exercices cessent à 09 h 42. Le médecin tombe à 09 h 47. Les ordres sont antérieurs.'),
('009', 'B', 'v330_runtime_trames', '1', 'LE RETRAIT PRÉCÈDE LA DÉCISION', 'Le Sujet 17 retire explicitement son consentement à 09 h 14. L''enregistrement original et le tableau des actes situent la poursuite du protocole après ce retrait. L''existence d''un formulaire signé plusieurs jours auparavant ne constitue pas un accord nouveau.', 'LE RETRAIT PRÉCÈDE LA DÉCISION', 'Le Sujet 17 retire son accord à 09 h 14. L’expérience continue malgré son refus.'),
('009', 'B', 'v330_runtime_trames', '2', 'UN AVIS D’ARRÊT, DES ACTES MAINTENUS', 'À 09 h 21, la direction adresse une recommandation écrite de suspension. Pourtant, une nouvelle étape est consignée à 09 h 34. Le rapprochement des registres doit encore établir qui a effectivement autorisé la poursuite et si l’avis a été respecté.', 'UN AVIS D’ARRÊT, DES ACTES MAINTENUS', 'La direction demande l’arrêt à 09 h 21. Une nouvelle étape de l’expérience a pourtant lieu à 09 h 34.'),
('009', 'B', 'v330_runtime_trames', '3', 'L''AMNÉSIE COMMENCE APRÈS LA SIGNATURE', 'Une alerte de détresse est consignée à 09 h 40, les exercices cessent à 09 h 42 et le médecin chute à 09 h 47. Des observations répétées étayent ensuite un trouble mnésique réel. Mais le registre signé par le médecin à 09 h 28 reste antérieur à sa chute, tandis que la direction avait recommandé une suspension à 09 h 21. Le défaut de suivi ne doit pas être confondu avec l''auteur de la décision.', 'SIGNATURE AVANT LA CHUTE', 'Le médecin signe à 09 h 28, puis tombe à 09 h 47 et perd réellement la mémoire. La direction avait demandé l’arrêt.'),
('009', 'C', 'v330_runtime_trames', '1', 'LE PREMIER COMPTE RENDU DISAIT NON', 'À 09 h 14, le Sujet 17 retire clairement son accord. La première note de l''équipe, mise sous empreinte numérique, reprend les termes du retrait. Le médecin demande alors une interruption documentée du protocole.', 'LE PREMIER COMPTE RENDU DISAIT NON', 'À 09 h 14, le Sujet 17 retire son accord. Le médecin demande d’arrêter l’expérience.'),
('009', 'C', 'v330_runtime_trames', '2', 'DEUX VERSIONS DU MÊME REFUS', 'La note originale consigne un retrait explicite. À 09 h 25, une version ultérieure remplace ce passage par une hésitation, alors que le programme ne s’arrête pas aussitôt. Le journal conserve les deux textes; le circuit de validation doit permettre d’attribuer la correction.', 'DEUX VERSIONS DU MÊME REFUS', 'La première note dit que le Sujet 17 refuse. À 09 h 25, une autre version parle seulement d’hésitation.'),
('009', 'C', 'v330_runtime_trames', '3', 'LA COPIE ET LA CHUTE', 'Les empreintes des notes antérieure et postérieure à 09 h 25 révèlent une réécriture de ''retrait'' en ''hésitation''. Une copie faite irrégulièrement par un membre d''équipe correspond à l''original archivé. Le médecin, qui avait demandé l''arrêt à 09 h 19, chute à 09 h 47 et présente ensuite une amnésie plausible. Les décisions datées et leurs auteurs doivent être reconstruits sans tirer de conclusion automatique du trouble de mémoire.', 'REFUS CONSERVÉ', 'Une copie conserve le refus initial. Le médecin avait demandé l’arrêt avant sa chute et son amnésie.'),
('010', 'A', 'v350_runtime_trames', '1', 'LA PORTE SE REFERME À 12 H 18', 'Un registre papier et des traces électroniques ne concordent pas sur l''accès d''un prestataire la veille. Nora a préparé un contrôle de conformité pour 14 h. Un badge du service et le contact de porte indiquent une fermeture à 12 h 18, mais l''identité du porteur effectif, sa connaissance de la défaillance intérieure et son intention restent à vérifier.', 'LA PORTE SE REFERME À 12 H 18', 'À 12 h 18, la porte de Nora se ferme. Un badge de service est utilisé, mais on ignore par qui.'),
('010', 'A', 'v350_runtime_trames', '2', 'LE PASSAGE DE 13 H 54', 'Une tournée logistique dans le secteur n''était pas mandatée pour ouvrir la réserve. À 13 h 54, une autorisation d''astreinte ouvre, puis le vantail est rabattu. Un passage d''astreinte non associé à un ordre de mission apparaît peu avant ; ces pièces peuvent expliquer la présence du second intervenant sans démontrer ce qu''il a compris en voyant Nora.', 'LE PASSAGE DE 13 H 54', 'À 13 h 54, une autorisation d’astreinte ouvre puis referme la réserve, sans mission prévue pour le faire.'),
('010', 'A', 'v350_runtime_trames', '3', 'CE QUE L''OUVERTURE CHANGE', 'La caméra muette montre Nora vivante au seuil pendant l''ouverture de 13 h 54. Une trace de service de la veille et une déclaration de contrôle rapprochent l''agent d''astreinte du passage irrégulier que Nora voulait signaler ; les enquêteurs doivent vérifier sa connaissance personnelle, l''absence d''ordre et les deux fermetures distinctes.', 'CE QUE L''OUVERTURE CHANGE', 'Une vidéo montre Nora vivante quand la porte s’ouvre à 13 h 54. On ignore ce que l’agent a compris.'),
('010', 'B', 'v350_runtime_trames', '1', 'UNE FERMETURE D''ESSAI', 'Une fiche de maintenance signale la poignée intérieure défectueuse, alors qu''un contrôle de service est déclaré effectué le matin. À 12 h 18, la porte se referme après une intervention extérieure, sans preuve de verrouillage commandé. Il faut séparer l''état réel du dispositif, la fiabilité des contrôles déclarés et la connaissance de l''occupation.', 'UNE FERMETURE D''ESSAI', 'À 12 h 18, la porte se referme. La poignée intérieure était défectueuse, sans ordre de verrouiller prouvé.'),
('010', 'B', 'v350_runtime_trames', '2', 'UN AVERTISSEMENT NON TRANSMIS', 'À 13 h 37, une collègue demande une vérification après des bruits et l''absence de Nora ; la demande est consultée sans être relayée. À 13 h 54, une dérogation d''astreinte ouvre la réserve, puis le contact de porte revient à fermé. Les capteurs n''indiquent pas si le vantail a été repoussé ou s''il s''est fermé par son rappel mécanique.', 'UN AVERTISSEMENT NON TRANSMIS', 'À 13 h 37, une demande de vérifier Nora est lue mais non transmise. La porte s’ouvre puis se referme à 13 h 54.'),
('010', 'B', 'v350_runtime_trames', '3', 'L''OUVERTURE N''A PAS SAUVÉ NORA', 'Un angle vidéo muet permet de distinguer le recul de l''agent, le vantail lâché puis refermé par son ferme-porte. Une feuille de contrôle signée à 9 h 05 est démentie par l''absence de passage au seuil sur la vidéo du créneau indiqué. Après la seconde fermeture, le badge aurait permis d''ouvrir de nouveau ; aucun secours n''a été appelé avant 14 h 10.', 'L''OUVERTURE N''A PAS SAUVÉ NORA', 'À 13 h 54, un agent lâche la porte, qui se referme seule. Il pouvait rouvrir, mais aucun secours n’est appelé avant 14 h 10.'),
('010', 'C', 'v350_runtime_trames', '1', 'UNE RESTRICTION INHABITUELLE', 'À 12 h 18, un contact de porte signale un rabattement de vantail. Une modification des badges ordinaires intervient à 12 h 19 et une note d''occupation est modifiée. La seule restriction des badges ne pourrait pas empêcher une sortie intérieure fonctionnelle ; il faut établir l''origine physique de l''enfermement et attribuer les manipulations.', 'UNE RESTRICTION INHABITUELLE', 'La porte se ferme à 12 h 18. Une minute plus tard, les badges ordinaires sont restreints.'),
('010', 'C', 'v350_runtime_trames', '2', 'UN MESSAGE PENDANT L''OUVERTURE', 'À 13 h 54, un badge d''astreinte ouvre malgré les restrictions. Une communication interne survient et une consigne de maintenir le local fermé est rapportée ; un message évoque aussi une intervention à venir. Il faut authentifier l''émetteur, les mots réellement reçus et vérifier si une quelconque alerte a effectivement été envoyée.', 'UN MESSAGE PENDANT L''OUVERTURE', 'À 13 h 54, un badge d’astreinte ouvre. Un message demande de garder la pièce fermée. Son auteur reste à identifier.'),
('010', 'C', 'v350_runtime_trames', '3', 'DEUX ACTES, UNE MÊME RÉTENTION', 'L''ouverture et la fermeture de 13 h 54 sont établies par la vidéo muette et le capteur. La communication authentifiée comporte une menace et une affirmation de prise en charge prochaine ; les registres du poste de sécurité n''en montrent aucune avant 14 h 10. Il faut distinguer la tromperie du supérieur du choix de l''agent de ne rien vérifier.', 'DEUX ACTES, UNE MÊME RÉTENTION', 'La porte se referme à 13 h 54. Un message promet une intervention, mais aucun secours n’apparaît avant 14 h 10.'),
('011', 'A', 'v370_runtime_trames', '1', 'AVIS IGNORÉ', 'H+00, le bureau juridique signale la présence de familles. H+03, le premier officier signe malgré la note civile.', 'AVIS IGNORÉ', 'Au début de l’opération, un juriste signale des familles dans la zone. Trois heures plus tard, un officier signe malgré l’alerte.'),
('011', 'A', 'v370_runtime_trames', '2', 'DES DÉCISIONS SUR LE TERRAIN', 'H+15, le commandant local maintient des décisions de terrain qui aggravent les destructions et débordent les consignes reçues.', 'DES DÉCISIONS SUR LE TERRAIN', 'À H+15, le commandant local maintient des actions plus destructrices que ce que les ordres permettaient.'),
('011', 'A', 'v370_runtime_trames', '3', 'SUSPENSION RETARDÉE', 'H+18, une alerte crédible est reçue. H+29, la suspension est encore retardée malgré les messages intervenus entre-temps.', 'SUSPENSION RETARDÉE', 'Une alerte arrive à H+18. À H+29, la suspension est toujours retardée.'),
('011', 'B', 'v370_runtime_trames', '1', 'LIMITES SIGNÉES', 'H+00, le premier officier signe un ordre limité qui exclut les secteurs habités de l''opération.', 'LIMITES SIGNÉES', 'À H+00, l’ordre signé exclut les zones habitées.'),
('011', 'B', 'v370_runtime_trames', '2', 'EXTENSION NON AUTORISÉE', 'H+11, le commandant local franchit le périmètre interdit par une décision prise sans nouvelle autorisation.', 'EXTENSION NON AUTORISÉE', 'À H+11, le commandant local entre dans une zone interdite sans nouvelle autorisation.'),
('011', 'B', 'v370_runtime_trames', '3', 'ALERTES ET RAPPORT RETOUCHÉ', 'Entre H+16 et H+26, plusieurs alertes sont reçues. La suspension intervient tard ; à H+36, le rapport local a été édulcoré.', 'ALERTES ET RAPPORT RETOUCHÉ', 'Des alertes arrivent entre H+16 et H+26. La suspension tarde et le rapport est minimisé à H+36.'),
('011', 'C', 'v370_runtime_trames', '1', 'UN ORDRE N''EST PAS UN BLANC-SEING', 'H+00, le premier officier approuve une mission risquée mais limitée ; il n''autorise pas l''extension ultérieure.', 'UN ORDRE N''EST PAS UN BLANC-SEING', 'À H+00, un officier valide une mission limitée. Il n’autorise pas son extension.'),
('011', 'C', 'v370_runtime_trames', '2', 'INITIATIVE ET AVERTISSEMENT', 'H+10, le responsable local élargit l''opération. H+13, le bureau de suspension reçoit un avertissement précis.', 'INITIATIVE ET AVERTISSEMENT', 'Le commandant local élargit l’opération à H+10. Une alerte arrive au bureau de suspension à H+13.'),
('011', 'C', 'v370_runtime_trames', '3', 'UNE ACCUSATION RÉÉCRITE', 'À H+36, le rapport initial a été réécrit par le bureau de suspension pour faire porter l''extension au premier officier.', 'UNE ACCUSATION RÉÉCRITE', 'À H+36, le bureau de suspension modifie le rapport pour accuser l’officier qui avait signé l’ordre initial.'),
('012', 'A', 'v390_runtime_trames', '1', 'H+00 — Téléphone consigné', 'À H+00, la direction signe l''ordre de garder Sacha sur place et de lui retirer son téléphone. Le texte vise sa liberté de sortir, sans mentionner de violence.', 'H+00 — Téléphone consigné', 'Au début, la direction ordonne de retenir Sacha et de lui prendre son téléphone. Elle ne demande pas de le frapper.'),
('012', 'A', 'v390_runtime_trames', '2', 'H+06 — Coups hors consigne', 'À H+06, un registre médical confirme des blessures apparues sous la garde du responsable de discipline. Le document initial ne contient aucun ordre de frapper Sacha.', 'H+06 — Coups hors consigne', 'Six heures plus tard, Sacha est blessé pendant sa garde. Aucun ordre écrit ne demandait de le frapper.'),
('012', 'A', 'v390_runtime_trames', '3', 'H+19 — Un passage volontaire', 'À H+19, une ronde reste sans signature. Sacha fuit peu après par une porte dont le verrou a été laissé libre. Le proche avait surveillé le couloir plusieurs heures.', 'H+19 — Un passage volontaire', 'Vers H+19, une ronde manque au registre. Sacha s’échappe peu après par une porte mal verrouillée.'),
('012', 'B', 'v390_runtime_trames', '1', 'H+00 — Parler ou retenir ?', 'La première instruction du dirigeant demande que Sacha reste à proximité pour une discussion. Elle n''évoque pas de porte verrouillée. Un ordre oral ultérieur du responsable impose pourtant un contrôle physique.', 'H+00 — Parler ou retenir ?', 'La direction demande seulement de parler à Sacha. Un responsable ordonne ensuite de le retenir.'),
('012', 'B', 'v390_runtime_trames', '2', 'H+11 — Une alerte lue', 'Une notification écrite explique à la direction que Sacha est enfermé contre sa volonté et présente des blessures. Le chef accuse réception à H+11, mais aucun ordre de libération immédiate n''est retrouvé.', 'H+11 — Une alerte lue', 'À H+11, la direction apprend que Sacha est enfermé et blessé. Aucun ordre de le libérer n’apparaît.'),
('012', 'B', 'v390_runtime_trames', '3', 'H+19 — Sortir sans autorisation', 'Le proche avait assuré des gardes. Il abandonne discrètement son poste vers H+19, permettant la fuite. Le chef n''avait toujours pas fait acter une décision claire de libération.', 'H+19 — Sortir sans autorisation', 'Vers H+19, un proche quitte sa garde et laisse Sacha s’enfuir. La direction n’a pas ordonné sa libération.'),
('012', 'C', 'v390_runtime_trames', '1', 'H+00 — Initiative individuelle', 'Le responsable de discipline consigne le téléphone et retient Sacha avant toute réunion ou signature du dirigeant. Les premiers registres ne mentionnent aucun ordre de la direction.', 'H+00 — Initiative individuelle', 'Un responsable enferme Sacha et prend son téléphone avant toute réunion ou ordre de la direction.'),
('012', 'C', 'v390_runtime_trames', '2', 'H+12 — La discrétion exigée', 'La direction apprend à H+12 que Sacha est enfermé et blessé. Une réponse demande de ne pas prévenir l''extérieur pour protéger la communauté ; elle ne commande ni libération ni soins immédiats.', 'H+12 — La discrétion exigée', 'À H+12, la direction sait que Sacha est blessé et enfermé. Elle demande le silence, pas sa libération.'),
('012', 'C', 'v390_runtime_trames', '3', 'H+19 — Aider après avoir gardé', 'Le proche occupe le couloir pendant plusieurs rondes, puis laisse un passage libre vers H+19. La sortie ne supprime ni son silence antérieur ni le choix tardif de la direction.', 'H+19 — Aider après avoir gardé', 'Vers H+19, le proche laisse un passage libre à Sacha, après avoir gardé le couloir pendant des heures.'),
('013', 'A', 'v410_runtime_trames', '1', 'C1 · Des mandats séparés', 'Les archives du réseau PERSEUS attestent que plusieurs intermédiaires ont travaillé sur le même dossier. Les instructions reçues par le coordinateur évoquent une action violente, sans désigner nommément la victime.', 'C1 · Des mandats séparés', 'PERSEUS a utilisé plusieurs intermédiaires. Le coordinateur a reçu un ordre violent sans nom de victime.'),
('013', 'A', 'v410_runtime_trames', '2', 'C2 · La cible connue du seul exécutant', 'Un extrait de correspondance confirme que le tireur connaissait l''identité du président avant les faits. L''enquête ne trouve pas de transmission nominative équivalente adressée au coordinateur.', 'C2 · La cible connue du seul exécutant', 'Le tireur savait que sa cible était le président. Rien ne prouve que le coordinateur connaissait son nom.'),
('013', 'A', 'v410_runtime_trames', '3', 'C3 · Une modification postérieure', 'L''historique des accès distingue une autorisation irrégulière préalable et une modification du registre enregistrée après la mort du président. Ces actes concernent le cadre de sécurité.', 'C3 · Une modification postérieure', 'Un accès irrégulier a eu lieu avant l’assassinat. Le registre de sécurité a été modifié après.'),
('013', 'B', 'v410_runtime_trames', '1', 'C1 · Une commande sans victime nommée', 'Le contrat reçu par le coordinateur évoque une opération d''intimidation grave. Aucun nom de victime n''y figure. Une seconde instruction, conservée séparément, désigne le président au tireur.', 'C1 · Une commande sans victime nommée', 'Le contrat du coordinateur parle d’intimidation, sans nom de victime. Un autre ordre désigne le président au tireur.'),
('013', 'B', 'v410_runtime_trames', '2', 'C2 · Deux circuits financiers', 'Les investigations relèvent deux flux de paiement indépendants : la préparation générale et un versement au cadre de sécurité. Cette séparation contredit l''idée d''une seule chaîne de financement entièrement connue.', 'C2 · Deux circuits financiers', 'Deux paiements différents ont financé la préparation générale et un cadre de sécurité.'),
('013', 'B', 'v410_runtime_trames', '3', 'C3 · Une accusation commode', 'Après l''assassinat, le cadre de sécurité accuse le coordinateur d''avoir choisi la cible. Les archives datées établissent que l''information nominative a circulé ailleurs et plus tard.', 'C3 · Une accusation commode', 'Après l’assassinat, le cadre de sécurité accuse le coordinateur. Les archives situent l’information sur la cible ailleurs.'),
('013', 'C', 'v410_runtime_trames', '1', 'C1 · Une anomalie antérieure', 'L''historique des accès présente une modification irrégulière antérieure au dernier ordre attribué au réseau. Le cadre de sécurité avait commencé à altérer les documents avant que le coordinateur tente de suspendre la mission.', 'C1 · Une anomalie antérieure', 'Le cadre de sécurité avait déjà modifié les dossiers avant la demande d’arrêt du coordinateur.'),
('013', 'C', 'v410_runtime_trames', '2', 'C2 · Une suspension sans accusé', 'Un message du coordinateur demande l''interruption de l''opération après une nouvelle alarmante. Aucun accusé de réception provenant du tireur n''est établi. Le meurtre a lieu malgré la demande.', 'C2 · Une suspension sans accusé', 'Le coordinateur demande l’arrêt de l’opération. Aucun reçu ne montre que le tireur a lu son message.'),
('013', 'C', 'v410_runtime_trames', '3', 'C3 · Qui pouvait encore agir ?', 'Le dossier distingue un coordinateur tardivement opposé à l''opération, un tireur n''ayant reçu aucun arrêt confirmé et un responsable de sécurité déjà engagé dans la dissimulation.', 'C3 · Qui pouvait encore agir ?', 'Le coordinateur avait demandé l’arrêt, sans confirmation du tireur. Le cadre de sécurité avait déjà masqué des faits.'),
('014', 'A', 'v430_runtime_trames', '1', 'C1 · L''export non autorisé', 'Le relevé d''audit confirme qu''un analyste a extrait plusieurs pages classifiées en dehors du processus prévu. Ces pages ne suffisaient pas, à elles seules, à identifier les onze informateurs.', 'C1 · L''export non autorisé', 'Un analyste a copié des pages secrètes hors procédure. Elles ne suffisaient pas à nommer les onze informateurs.'),
('014', 'A', 'v430_runtime_trames', '2', 'C2 · La liste recomposée', 'Des fragments issus de plusieurs dossiers ont été rapprochés après le premier export. Le résultat final contenait les onze identités et les informations de proches, absentes du lot initial.', 'C2 · La liste recomposée', 'Des fragments ont ensuite été réunis en une liste de onze noms, avec des informations sur leurs familles.'),
('014', 'A', 'v430_runtime_trames', '3', 'C3 · Vente et dissimulation distinctes', 'Un versement associé à l''officier traitant est confirmé dans le dossier d''enquête. Les retouches du journal de sécurité concernent une anomalie que le responsable voulait cacher, sans prouver qu''il a vendu les identités.', 'C3 · Vente et dissimulation distinctes', 'Un paiement lié à l’officier est retrouvé. Le responsable sécurité a modifié les journaux, sans preuve qu’il ait vendu les noms.'),
('014', 'B', 'v430_runtime_trames', '1', 'C1 · Une mesure de protection incomplète', 'Une note interne présente la copie des données comme destinée à protéger en urgence des informateurs menacés. L''autorisation et le contrôle de son destinataire n''ont toutefois jamais été finalisés.', 'C1 · Une mesure de protection incomplète', 'Une note dit que la copie devait protéger des informateurs. Son destinataire n’avait pas encore été vérifié.'),
('014', 'B', 'v430_runtime_trames', '2', 'C2 · Un destinataire non vérifié', 'L''officier traitant croyait faire parvenir le dossier à un service d''évacuation habilité. Une vérification administrative ultérieure démontre que le mandat du destinataire n''avait pas été confirmé.', 'C2 · Un destinataire non vérifié', 'L’officier croyait envoyer les noms à un service autorisé. Le mandat de ce service n’était pas confirmé.'),
('014', 'B', 'v430_runtime_trames', '3', 'C3 · L''alerte restée sans suite', 'Le responsable sécurité avait reçu une alerte signalant l''incertitude autour de la transmission. Il l''a laissée sans traitement, craignant d''exposer les erreurs de son service. Aucun accord de vente n''a été retrouvé.', 'C3 · L''alerte restée sans suite', 'Le responsable sécurité avait reçu une alerte sur l’envoi, mais ne l’a pas traitée. Aucune vente n’est prouvée.'),
('014', 'C', 'v430_runtime_trames', '1', 'C1 · Un accès initialement autorisé', 'Un mandat officiel autorise une consultation limitée des dossiers. L''officier traitant utilise toutefois cet accès à une fin étrangère à la mission, sans être autorisé à communiquer les identités.', 'C1 · Un accès initialement autorisé', 'L’officier pouvait consulter certains dossiers, pas transmettre les noms. Il a utilisé son accès à une autre fin.'),
('014', 'C', 'v430_runtime_trames', '2', 'C2 · Une intrusion jamais établie', 'La piste d''une attaque externe repose sur des anomalies d''audit non confirmées. L''enquête relève plutôt des usages de droits déjà accordés et une incapacité interne à suivre correctement les consultations.', 'C2 · Une intrusion jamais établie', 'Aucune attaque externe n’est prouvée. Les données ont surtout été consultées avec des accès déjà autorisés.'),
('014', 'C', 'v430_runtime_trames', '3', 'C3 · Détournement et fausse piste', 'L''officier traitant a communiqué des identités hors de son mandat. La sécurité laisse prospérer l''hypothèse d''une intrusion étrangère malgré l''absence de preuve, ce qui détourne l''enquête de l''abus interne.', 'NOMS DIFFUSÉS SANS AUTORISATION', 'Des noms ont été diffusés hors autorisation. Les journaux ne prouvent pas d’intrusion étrangère.'),
('015', 'A', 'v450_runtime_trames', '1', 'C1 — L''alerte que la direction a reçue', 'Le dossier contient une recommandation explicite de suspendre ÉLIGIBLES. La direction en accuse réception avant de demander la poursuite. La gravité du risque était connue et discutée.', 'C1 — L''alerte que la direction a reçue', 'La direction reçoit une note demandant d’arrêter ÉLIGIBLES, puis demande de continuer.'),
('015', 'A', 'v450_runtime_trames', '2', 'C2 — Signer malgré sa réserve', 'Le clinicien exprime son opposition à la poursuite, puis signe une décision de maintien après un échange avec le responsable du programme. Sa réserve demeure dans une version conservée du dossier.', 'C2 — Signer malgré sa réserve', 'Le clinicien déconseille la poursuite, mais signe finalement le maintien du programme.'),
('015', 'A', 'v450_runtime_trames', '3', 'C3 — Après la mort, les formulations changent', 'Le patient décède alors que le programme n''a pas été interrompu. Plusieurs alertes sont atténuées dans des notes produites ensuite. La modification documentaire ne déplace pas la décision initiale du dirigeant.', 'C3 — Après la mort, les formulations changent', 'Après la mort, des notes atténuent les alertes. La décision de poursuivre avait été prise avant.'),
('015', 'B', 'v450_runtime_trames', '1', 'C1 — La suspension signée', 'La direction donne son accord pour suspendre ÉLIGIBLES. La décision datée précède la nouvelle signature du clinicien autorisant la poursuite.', 'C1 — La suspension signée', 'La direction avait accepté la suspension. Plus tard, le clinicien a signé pour continuer.'),
('015', 'B', 'v450_runtime_trames', '2', 'C2 — Une décision clinique contraire', 'Le clinicien choisit de maintenir le programme malgré l''accord d''arrêt déjà reçu. Aucun nouveau visa du dirigeant ne valide cette poursuite.', 'C2 — Une décision clinique contraire', 'Le clinicien maintient le programme malgré l’ordre d’arrêt. Aucun nouvel accord de la direction n’apparaît.'),
('015', 'B', 'v450_runtime_trames', '3', 'C3 — La contradiction maquillée', 'Après le décès, deux décisions opposées sont présentées dans les notes retouchées comme une seule démarche continue, contrairement aux archives originales.', 'DEUX DÉCISIONS CONTRADICTOIRES', 'Après la mort, des notes modifiées présentent deux décisions opposées comme une seule.'),
('015', 'C', 'v450_runtime_trames', '1', 'C1 — Une réévaluation sans accusé', 'La direction accepte le principe d''une réévaluation et le clinicien rédige une demande de sortie. Aucun accusé de prise en charge opérationnelle n''est conservé au moment où la décision aurait dû progresser.', 'C1 — Une réévaluation sans accusé', 'La direction accepte une réévaluation et le clinicien demande la sortie. Aucun service ne confirme la prise en charge.'),
('015', 'C', 'v450_runtime_trames', '2', 'C2 — Le dossier demeure bloqué', 'Le document nécessaire à la sortie reste au service administratif. Ce blocage prolonge la présence du patient dans ÉLIGIBLES alors même qu''une réévaluation avait été demandée.', 'C2 — Le dossier demeure bloqué', 'Le dossier de sortie reste bloqué à l’administration. Le patient reste dans le programme.'),
('015', 'C', 'v450_runtime_trames', '3', 'C3 — Le retard réécrit après le décès', 'Les pièces retravaillées après la mort présentent le retard comme un simple délai de transmission, alors qu''une version antérieure établit que le dossier a été retenu malgré les alertes.', 'C3 — Le retard réécrit après le décès', 'Après le décès, le dossier présente le blocage comme un simple retard d’envoi. L’ancienne version dit autre chose.'),
('016', 'A', 'v480_runtime_trames', '1', 'L''image incomplète', 'Le film authentifié prouve l''enlèvement et les humiliations. Il s''interrompt avant les circonstances médicales du décès; la coupure ne suffit pas à attribuer un geste mortel.', 'L''image incomplète', 'La vidéo montre l’enlèvement et les humiliations, mais s’arrête avant les faits qui ont causé la mort.'),
('016', 'A', 'v480_runtime_trames', '2', 'La période hors champ', 'Les accès et la caméra du palier situent l''organisateur hors de la zone critique. L''exécutant demeure seul au dernier étage après l''arrêt de la vidéo.', 'La période hors champ', 'L’organisateur a quitté l’étage avant la fin de la vidéo. L’exécutant y reste seul.'),
('016', 'A', 'v480_runtime_trames', '3', 'La cause du décès', 'L''autopsie révèle une lésion létale postérieure à la coupure, distincte des violences filmées. Une trace sur l''objet associé recoupe la présence de l''exécutant, seul durant la fenêtre de décès.', 'BLESSURE APRÈS LA VIDÉO', 'Une blessure mortelle apparaît après la coupure. L’objet et les accès donnent des pistes sur la personne présente.'),
('016', 'B', 'v470_runtime_trames', '1', 'C1 · Une séquence interrompue', 'La vidéo montre la détention et les violences, mais s''arrête sans enregistrer le meurtre. Le film ne permet pas de décider qui a frappé après la coupure.', 'C1 · Une séquence interrompue', 'La vidéo montre les violences, mais pas le meurtre. On ignore qui a frappé après la coupure.'),
('016', 'B', 'v470_runtime_trames', '2', 'C2 · Un retour dissimulé', 'Le premier départ de l''organisateur est attesté. Un autre relevé démontre pourtant sa présence de nouveau sur les lieux après l''arrêt de la caméra.', 'C2 · Un retour dissimulé', 'L’organisateur quitte les lieux, puis revient après l’arrêt de la caméra.'),
('016', 'B', 'v470_runtime_trames', '3', 'C3 · L''alibi contredit par un témoin', 'L''exécutant a assisté au retour et au geste mortel de l''organisateur. Son récit de départ définitif est contredit. L''intermédiaire voulait faire arrêter la scène sans connaître le retour.', 'C3 · L''alibi contredit par un témoin', 'Un témoin contredit l’alibi de l’organisateur. Les relevés confirment son retour.'),
('016', 'B', 'v480_runtime_trames', '1', 'L''image incomplète', 'Le film authentifié prouve l''enlèvement et les humiliations. Il s''interrompt avant les circonstances médicales du décès; la coupure ne suffit pas à attribuer un geste mortel.', 'L''image incomplète', 'La vidéo montre l’enlèvement et les humiliations, mais s’arrête avant les faits qui ont causé la mort.'),
('016', 'B', 'v480_runtime_trames', '2', 'La période hors champ', 'Le premier départ de l''organisateur est attesté. Un second accès indépendant démontre son retour après la coupure pendant que l''exécutant est encore sur place.', 'La période hors champ', 'Après un premier départ, l’organisateur revient sur place. L’exécutant y est encore.'),
('016', 'B', 'v480_runtime_trames', '3', 'La cause du décès', 'Les constatations médico-légales établissent une lésion létale après la coupure. Des traces matérielles recoupées avec les accès relient le geste à l''organisateur revenu sur les lieux.', 'BLESSURE APRÈS LA VIDÉO', 'Une blessure mortelle apparaît après la coupure. Des traces situent l’organisateur revenu pendant cette période.'),
('016', 'C', 'v480_runtime_trames', '1', 'L''image incomplète', 'La vidéo établit la séquestration et la sédation. Les derniers plans montrent déjà une dégradation de l''état de la victime, sans préciser sa cause médicale définitive.', 'L''image incomplète', 'La vidéo montre la victime retenue et droguée. Son état se dégrade avant la coupure.'),
('016', 'C', 'v480_runtime_trames', '2', 'La période hors champ', 'L''exécutant demeure auprès de la victime en détresse après l''arrêt du film. Le journal des communications ne relève aucun appel aux secours pendant une fenêtre d''intervention utile.', 'La période hors champ', 'L’exécutant reste auprès de la victime après la coupure. Aucun appel aux secours n’est enregistré.'),
('016', 'C', 'v480_runtime_trames', '3', 'La cause du décès', 'L''autopsie et la toxicologie attribuent le décès au cumul des violences et de la sédation. Elles ne retrouvent pas de blessure fatale nouvelle après le film. L''absence d''alerte a supprimé une possibilité d''assistance.', 'CAUSE MÉDICALE', 'L’autopsie relie la mort aux violences et aux sédatifs. Aucune nouvelle blessure mortelle n’est trouvée après la vidéo.'),
('017', 'A', 'v320_runtime_trames', '1', 'L''EMPREINTE D''UNE CONTRAINTE', 'Le rapport médico-légal décrit une compression thoracique et une détresse respiratoire survenues durant la garde. Une photographie de constat et une déposition concordent sur la position de maintien imposée par le gardien. La seule présence d''une blessure ne suffit pas à identifier qui a ordonné le geste.', 'L''EMPREINTE D''UNE CONTRAINTE', 'La victime a été maintenue de force et a eu du mal à respirer. Une photo et un témoignage confirment la position imposée.'),
('017', 'A', 'v320_runtime_trames', '2', 'L''ALERTE REÇUE', 'Une note d''alerte portant une heure de réception et le journal des communications établissent que l''organisateur a été averti d''une détresse grave pendant que le captif était vivant. Aucune demande d''assistance n''apparaît ensuite dans le registre. Les traces prouvent le report, sans garantir qu''un secours aurait sauvé la personne.', 'L''ALERTE REÇUE', 'L’organisateur avait reçu une alerte sur le captif encore vivant. Aucun appel aux secours n’apparaît après.'),
('017', 'A', 'v320_runtime_trames', '3', 'L''ARGENT APRÈS LA MORT', 'Le certificat d''intervention situe le décès avant la première connexion de l''intermédiaire. Le relevé financier et le reçu de libération du survivant sont postérieurs. Ils documentent l''achat d''un silence, mais ne placent pas l''intermédiaire au moment de la contrainte ni au moment de l''alerte. Les trois horodatages sont de sources distinctes.', 'L''ARGENT APRÈS LA MORT', 'Un paiement suit la mort, avant la libération du survivant. Il ne place pas l’intermédiaire au moment du décès.'),
('017', 'B', 'v320_runtime_trames', '1', 'LE BLESSÉ POUVAIT ENCORE ÊTRE PRIS EN CHARGE', 'Une fiche d''observation datée et un rapport médical décrivent le captif vivant après une violence grave. Le dossier établit qu''une intervention restait matériellement possible, pas qu''elle aurait certainement sauvé le captif.', 'LE BLESSÉ POUVAIT ENCORE ÊTRE PRIS EN CHARGE', 'La victime était encore vivante après de graves violences. Des secours restaient possibles, sans garantie de survie.'),
('017', 'B', 'v320_runtime_trames', '2', 'UNE OFFRE ÉCRITE, UN REFUS CONSIGNÉ', 'Le registre de transport mentionne un véhicule disponible, une destination d''accueil et une proposition d''évacuation reçue par l''organisateur. Une instruction de poursuivre la rétention est horodatée quelques minutes plus tard. Ce refus est distinct du coup initial porté par le gardien.', 'UNE OFFRE ÉCRITE, UN REFUS CONSIGNÉ', 'Un véhicule et un lieu d’accueil avaient été proposés pour évacuer la victime. L’organisateur a ordonné de la garder.'),
('017', 'B', 'v320_runtime_trames', '3', 'LE RETARD A UN AUTEUR', 'Le relevé des ordres lie expressément la prolongation à l''exigence de négociation de l''organisateur ; l''offre d''assistance précède la détérioration terminale. La première intervention de l''intermédiaire est postérieure au décès. Les pièces établissent la responsabilité du refus sans inventer un homicide intentionnel.', 'LE RETARD A UN AUTEUR', 'L’organisateur prolonge la détention malgré une offre de secours. L’intermédiaire intervient après la mort.'),
('017', 'C', 'v320_runtime_trames', '1', 'UNE PREMIÈRE SORTIE ENVISAGÉE', 'Le registre de garde enregistre une discussion sur la sortie des deux captifs, puis un maintien prolongé. Il existe une rupture entre la date de la sortie initialement prévue et le moment de l''aggravation du captif. L''identité du demandeur n''est pas encore connue.', 'UNE PREMIÈRE SORTIE ENVISAGÉE', 'La sortie des deux captifs avait été discutée, puis retardée. On ignore qui l’a demandé.'),
('017', 'C', 'v320_runtime_trames', '2', 'L''ORDRE VIENT D''UNE NÉGOCIATION', 'Une communication authentifiée situe le contact de l''intermédiaire avant le décès. Le message porte sur une nouvelle concession exigée du comptable ; une instruction de ne pas libérer les captifs suit cette demande. Les journaux de transmission relient les deux événements, sans attribuer au négociateur le geste physique du gardien.', 'L''ORDRE VIENT D''UNE NÉGOCIATION', 'Un intermédiaire contacte le groupe avant la mort pour exiger davantage. Un ordre de garder les captifs suit.'),
('017', 'C', 'v320_runtime_trames', '3', 'LE MESSAGE EFFACÉ AVAIT UNE DATE', 'L''archive technique conserve l''horodatage antérieur au décès du message envoyé par l''intermédiaire. Le système journalise aussi sa suppression ultérieure. Le retour du conducteur et le reçu d''accord de silence sont postérieurs à la mort. Le mensonge selon lequel toute intervention financière serait intervenue après la mort est matériellement réfuté.', 'LE MESSAGE EFFACÉ AVAIT UNE DATE', 'Un message de l’intermédiaire date d’avant la mort, puis a été effacé. Le reçu d’accord de silence est postérieur.'),
('018', 'A', 'v540_runtime_trames', '1', 'DES PASSAGES NON SIMULTANÉS', 'Les relevés distinguent plusieurs visites. Une présence collective des neuf anciens résidents n''est attestée par rien.', 'DES PASSAGES NON SIMULTANÉS', 'Les neuf anciens résidents ne sont jamais vus ensemble. Les relevés montrent plusieurs visites séparées.'),
('018', 'A', 'v540_runtime_trames', '2', 'LA TABLE A BOUGÉ', 'La disposition de la table est postérieure à un désordre; la seule manipulation des objets ne désigne aucun auteur.', 'LA TABLE A BOUGÉ', 'La table a été déplacée après que la pièce a été dérangée. Cela ne dit pas qui a tué la victime.'),
('018', 'A', 'v540_runtime_trames', '3', 'LA CHRONOLOGIE À RECONSTRUIRE', 'Une arrivée tardive et une première confrontation apparaissent distinctes, mais les déclarations doivent encore être confrontées.', 'DEUX MOMENTS DISTINCTS', 'Une personne arrive tard, après une première confrontation. On ignore encore le lien entre les deux moments.'),
('018', 'B', 'v540_runtime_trames', '1', 'DEUX DISCUSSIONS SÉPARÉES', 'Plusieurs rencontres avec le directeur sont attestées; aucune n''est encore identifiée comme celle du geste mortel.', 'DEUX DISCUSSIONS SÉPARÉES', 'Plusieurs personnes ont rencontré le directeur. On ignore laquelle l’a vu au moment du meurtre.'),
('018', 'B', 'v540_runtime_trames', '2', 'UN DIFFÉREND COMPTABLE', 'Un litige financier se rattache à la période entourant les violences, sans attribution personnelle définitive.', 'UN DIFFÉREND COMPTABLE', 'Une dispute d’argent apparaît pendant les événements, sans preuve sur son responsable.'),
('018', 'B', 'v540_runtime_trames', '3', 'UNE SCÈNE COMPOSÉE PLUS TARD', 'Les assiettes ont été disposées après la phase mortelle; cette intervention ne prouve pas qui a tué.', 'UNE SCÈNE COMPOSÉE PLUS TARD', 'Les assiettes ont été placées après la mort. Leur disposition ne désigne pas le meurtrier.'),
('018', 'C', 'v540_runtime_trames', '1', 'UN RENDEZ-VOUS CONTESTÉ', 'Des communications évoquent une pression collective sur le directeur; leur portée exacte reste à établir.', 'UN RENDEZ-VOUS CONTESTÉ', 'Des messages montrent que plusieurs personnes voulaient faire pression sur le directeur.'),
('018', 'C', 'v540_runtime_trames', '2', 'DES ARRIVÉES DISTINCTES', 'Les passages et les traces de lutte suggèrent des interventions séparées; les données ne révèlent pas directement l''auteur.', 'DES ARRIVÉES DISTINCTES', 'Les arrivées et les traces de lutte montrent des passages distincts, sans identifier qui a tué.'),
('018', 'C', 'v540_runtime_trames', '3', 'UN SYMBOLE POSTÉRIEUR', 'La table a été dressée après la mort; un projet antérieur ne rend pas automatiquement chaque participant responsable du geste fatal.', 'UN SYMBOLE POSTÉRIEUR', 'La table a été dressée après la mort. Un projet commun ne prouve pas que tous ont participé au meurtre.'),
('019', 'A', 'v570_runtime_trames', '1', 'DEUX VERSIONS', 'La chemise publique du lanceur d''alerte ne correspond pas à l''inventaire de son dossier intégral. Certaines annexes sont manquantes.', 'DEUX VERSIONS', 'La version publique du dossier financier manque plusieurs annexes présentes dans la copie complète.'),
('019', 'A', 'v570_runtime_trames', '2', 'UNE INTERCEPTION HORS REGISTRE', 'Le dispositif de sécurité a été modifié dans un couloir technique. La mission commandée et la manière dont elle a été exécutée demandent deux vérifications indépendantes.', 'UNE INTERCEPTION HORS REGISTRE', 'La sécurité a changé les accès d’un couloir technique. On ignore qui a demandé ce changement.'),
('019', 'A', 'v570_runtime_trames', '3', 'DES COMPTES ET DES COPIES', 'Des prestations de sécurité non justifiées figurent dans l''annexe complète. Une suppression administrative datée après le décès concerne un autre ensemble de pièces.', 'DES COMPTES ET DES COPIES', 'Des dépenses de sécurité non justifiées figurent dans une annexe. D’autres pièces ont été supprimées après la mort.'),
('019', 'B', 'v570_runtime_trames', '1', 'UN ENTRETIEN HORS PROGRAMME', 'L''ordre du jour ne mentionne pas une rencontre privée que deux personnels du gala disent avoir préparée. Les documents ne décrivent pas la teneur de cette discussion.', 'UN ENTRETIEN HORS PROGRAMME', 'Deux employés ont préparé une réunion privée absente du programme du gala.'),
('019', 'B', 'v570_runtime_trames', '2', 'LE SALON SANS SURVEILLANCE', 'La ronde a été déplacée tandis qu''un salon réservé était ouvert. Les journaux des accès et la coupure vidéo doivent être interprétés séparément.', 'LE SALON SANS SURVEILLANCE', 'Une ronde de sécurité a été déplacée pendant qu’un salon privé restait ouvert. La vidéo est coupée.'),
('019', 'B', 'v570_runtime_trames', '3', 'DEUX JOURNAUX D''ACCÈS', 'Une copie indépendante montre une modification tardive du registre de sécurité. Elle doit être rapprochée de l''heure de la rencontre privée et des issues réservées.', 'DEUX JOURNAUX D''ACCÈS', 'Une copie indépendante montre un changement tardif du registre des accès.'),
('019', 'C', 'v570_runtime_trames', '1', 'DEUX VERSIONS', 'L''inventaire annoncé avant le gala comporte des annexes absentes du dossier destiné à la presse. Plusieurs services possédaient des copies partielles.', 'DEUX VERSIONS', 'Le dossier remis à la presse manque plusieurs annexes présentes dans l’inventaire initial.'),
('019', 'C', 'v570_runtime_trames', '2', 'DES JOURNAUX INCOMPATIBLES', 'Un même passage est décrit différemment dans un relevé administratif et dans une trace technique. Leur origine et leur date de création doivent être comparées.', 'DES JOURNAUX INCOMPATIBLES', 'Le même passage apparaît différemment dans un registre administratif et un relevé technique.'),
('019', 'C', 'v570_runtime_trames', '3', 'UN EXPORT RECONSTITUÉ', 'Le relevé transmis après le décès contient une modification non répercutée dans la sauvegarde d''origine. Le dossier complet éclaire l''intérêt d''une telle intervention.', 'UN EXPORT RECONSTITUÉ', 'Un relevé envoyé après la mort a été modifié. La sauvegarde d’origine ne contient pas ce changement.'),
('020', 'A', 'v590_runtime_trames', '1', 'DÉPART DE FEU PROVOQUÉ', 'L’analyse établit un départ de feu volontaire et limité à l’origine, distinct des mécanismes ayant piégé la foule.', 'DÉPART DE FEU PROVOQUÉ', 'Le feu a commencé volontairement, mais était limité au départ. D’autres problèmes ont piégé la foule.'),
('020', 'A', 'v590_runtime_trames', '2', 'LES ISSUES RESTENT RESTREINTES', 'Des avertissements sur des portes inutilisables étaient connus avant le gala ; la direction maintient les restrictions.', 'LES ISSUES RESTENT RESTREINTES', 'La direction connaissait le problème des sorties avant le gala, mais a maintenu les restrictions.'),
('020', 'A', 'v590_runtime_trames', '3', 'L’ALERTE N’EST PAS SUIVIE', 'Le coordinateur prend connaissance des premiers signes sans ordonner immédiatement l’évacuation ; plusieurs facteurs amplifient le bilan.', 'L’ALERTE N’EST PAS SUIVIE', 'Le coordinateur voit les premiers signaux, mais n’ordonne pas tout de suite l’évacuation.'),
('020', 'A', 'v600_runtime_trames', '1', 'LE PLAN ET SES LIMITES', 'Le plan des espaces montre plusieurs cheminements possibles vers l''extérieur. Mais la capacité d''évacuation réelle dépendait aussi de restrictions de service appliquées avant la soirée.', 'LE PLAN ET SES LIMITES', 'Le plan prévoit plusieurs sorties, mais des restrictions du service limitaient leur utilisation.'),
('020', 'A', 'v600_runtime_trames', '2', 'UNE CONSIGNE NON LEVÉE', 'Une note de gestion mentionne des issues secondaires restreintes et des recommandations de vérification encore ouvertes. Le document ne précise pas leur état pendant l''alarme.', 'UNE CONSIGNE NON LEVÉE', 'Une note signale des issues restreintes et des contrôles non terminés. Leur état pendant l’alarme reste inconnu.'),
('020', 'A', 'v600_runtime_trames', '3', 'LES CONTRÔLES AVANT LE BAL', 'Les journaux de préparation font apparaître une réserve technique non levée et un contrôle d''accès raccourci. Il faut déterminer qui disposait de chaque information.', 'LES CONTRÔLES AVANT LE BAL', 'Une réserve technique restait ouverte et un contrôle d’accès avait été écourté avant le gala.'),
('020', 'A', 'v600_runtime_trames', '4', 'LES PREMIERS SIGNAUX', 'Les premiers témoignages décrivent un incident localisé avant une alerte plus importante. Les récits ne concordent pas encore sur l''instant du départ du feu.', 'LES PREMIERS SIGNAUX', 'Les premiers témoins parlent d’un incident local, puis d’une alerte plus grave. Ils ne s’accordent pas sur le début.'),
('020', 'A', 'v600_runtime_trames', '5', 'LES VERSIONS DU RAPPORT', 'Une expertise recoupe l''heure des accès et les traces du foyer : une intervention volontaire provoque le départ du feu, indépendamment des défauts de protection et des restrictions de sortie. Le constat ne prouve aucune intention de provoquer le bilan humain.', 'LES VERSIONS DU RAPPORT', 'L’expertise montre un départ de feu volontaire. Les défauts de sécurité ont ensuite aggravé le danger.'),
('020', 'A', 'v600_runtime_trames', '6', 'DEUX CHRONOLOGIES À RECROISER', 'Les journaux montrent un premier signal interprété comme incident local, puis des alertes plus graves avant l''annonce générale. Le délai relève d''une appréciation insuffisante du risque, sans ordre conservé de privilégier un groupe d''invités.', 'DEUX CHRONOLOGIES À RECROISER', 'Une première alerte a été prise pour un incident mineur. L’alarme générale a été déclenchée plus tard.'),
('020', 'B', 'v590_runtime_trames', '1', 'AUCUNE MISE À FEU VOLONTAIRE PROUVÉE', 'Une défaillance accidentelle documentée précède l''incendie. La présence de l''activiste ne suffit pas à désigner un auteur du feu.', 'AUCUNE MISE À FEU VOLONTAIRE PROUVÉE', 'Une panne technique a précédé le feu. La présence de l’activiste ne prouve pas qu’il l’ait allumé.'),
('020', 'B', 'v590_runtime_trames', '2', 'DES SORTIES BLOQUÉES MALGRÉ LES SIGNALEMENTS', 'Les instructions de gestion maintiennent des issues fermées alors que des réserves techniques avaient été remises.', 'DES SORTIES BLOQUÉES MALGRÉ LES SIGNALEMENTS', 'Des sorties sont restées fermées malgré les signalements de problèmes.'),
('020', 'B', 'v590_runtime_trames', '3', 'UNE FAUSSE ASSURANCE DE SÉCURITÉ', 'Le rapport de contrôle favorable, malgré ses lacunes, retarde la décision du coordinateur ; l''absence d''incendie volontaire n''efface pas les responsabilités humaines.', 'UNE FAUSSE ASSURANCE DE SÉCURITÉ', 'Un rapport trop rassurant a retardé l’évacuation. Le feu accidentel n’efface pas les fautes de sécurité.'),
('020', 'B', 'v600_runtime_trames', '1', 'LE PLAN ET SES LIMITES', 'Le plan du bâtiment prévoit plusieurs sorties secondaires, mais leur disponibilité effective n''avait pas été confirmée dans la configuration retenue pour la réception.', 'LE PLAN ET SES LIMITES', 'Le plan prévoit plusieurs sorties. Leur ouverture le soir du bal n’avait pas été confirmée.'),
('020', 'B', 'v600_runtime_trames', '2', 'UNE CONSIGNE NON LEVÉE', 'Une demande de contrôle final des accès avait été inscrite au planning. Un autre document indique que la ronde n''a finalement pas été menée.', 'UNE CONSIGNE NON LEVÉE', 'Un contrôle final des sorties était prévu, mais la ronde n’a pas été faite.'),
('020', 'B', 'v600_runtime_trames', '3', 'LES CONTRÔLES AVANT LE BAL', 'Une première note signale des réserves sur la sécurité technique alors qu''un document diffusé aux organisateurs mentionne une conformité sans réserve explicative.', 'LES CONTRÔLES AVANT LE BAL', 'Une note signalait des problèmes techniques. Le rapport transmis aux organisateurs disait que tout était conforme.'),
('020', 'B', 'v600_runtime_trames', '4', 'LES PREMIERS SIGNAUX', 'Des témoignages placent l''activiste à proximité d''une zone de service avant la fumée; ils ne décrivent aucun geste permettant d''attribuer le départ du feu.', 'LES PREMIERS SIGNAUX', 'L’activiste était près d’une zone de service avant la fumée. Personne ne l’a vu allumer le feu.'),
('020', 'B', 'v600_runtime_trames', '5', 'LES VERSIONS DU RAPPORT', 'Une expertise indépendante des composants du foyer confirme une défaillance technique accidentelle. La présence antérieure de l''activiste ne permet pas de lui attribuer un geste d''allumage; un rapport trop favorable avait masqué des anomalies.', 'LES VERSIONS DU RAPPORT', 'L’expertise attribue le feu à une panne. La présence de l’activiste ne prouve rien sur son départ.'),
('020', 'B', 'v600_runtime_trames', '6', 'DEUX CHRONOLOGIES À RECROISER', 'Les alarmes et les communications documentent un retard de réaction nourri par une confiance injustifiée dans le rapport de conformité; aucun avis urgent compris puis volontairement écarté n''est établi.', 'DEUX CHRONOLOGIES À RECROISER', 'Les alarmes ont été traitées trop tard à cause d’un rapport de sécurité trop rassurant.'),
('020', 'C', 'v590_runtime_trames', '1', 'UNE CONSIGNE NON LEVÉE', 'Une note de production et des réserves anciennes ne sont pas intégralement reprises dans la version publique du programme du gala. Il faut en vérifier la portée et les signataires.', 'UNE CONSIGNE NON LEVÉE', 'Des avertissements de sécurité ne figurent pas dans la version publique du programme du gala.'),
('020', 'C', 'v590_runtime_trames', '2', 'LES PREMIERS SIGNAUX', 'Le journal d''alarme et les premières dépositions montrent une différence entre la perception d''un incident scénique et la compréhension d''un danger réel.', 'LES PREMIERS SIGNAUX', 'Les premiers signaux ont été pris pour un problème de scène, puis le danger a été reconnu.'),
('020', 'C', 'v590_runtime_trames', '3', 'DEUX CHRONOLOGIES À RECROISER', 'Le journal de réception, l''avis technique urgent et les communications d''ordre montrent que la coordination a différé l''annonce générale pour maintenir le passage d''une délégation VIP. Ce choix suit la compréhension du danger.', 'ALARME RETARDÉE POUR LES VIP', 'Des messages montrent que l’alarme a été repoussée pendant le passage d’une délégation VIP.'),
('020', 'C', 'v600_runtime_trames', '1', 'LE PLAN ET SES LIMITES', 'Le plan d''accueil distingue les accès ordinaires des couloirs réservés aux donateurs. Les circulations imposées par le protocole ont modifié la capacité effective de sortie.', 'LE PLAN ET SES LIMITES', 'Le plan séparait les sorties normales et les couloirs réservés aux donateurs. Cela réduisait le passage possible.'),
('020', 'C', 'v600_runtime_trames', '2', 'UNE CONSIGNE NON LEVÉE', 'Une note de production et des réserves anciennes ne sont pas intégralement reprises dans la version publique du programme du gala. Il faut en vérifier la portée et les signataires.', 'UNE CONSIGNE NON LEVÉE', 'Des avertissements de sécurité ne figurent pas dans la version publique du programme du gala.'),
('020', 'C', 'v600_runtime_trames', '3', 'LES CONTRÔLES AVANT LE BAL', 'Un contrôle des installations n''était pas clôturé avant le numéro final. Le document ne démontre pas directement quel événement a commencé l''incendie.', 'LES CONTRÔLES AVANT LE BAL', 'Un contrôle des installations n’était pas fini avant le dernier numéro.'),
('020', 'C', 'v600_runtime_trames', '4', 'LES PREMIERS SIGNAUX', 'Le journal d''alarme et les premières dépositions montrent une différence entre la perception d''un incident scénique et la compréhension d''un danger réel.', 'LES PREMIERS SIGNAUX', 'Les premiers signaux ont été pris pour un problème de scène, puis le danger a été reconnu.'),
('020', 'C', 'v600_runtime_trames', '5', 'LES VERSIONS DU RAPPORT', 'Une copie indépendante du programme de régie, croisée avec les traces du foyer, établit qu''un effet scénique autorisé tardivement a provoqué accidentellement l''incendie. L''activiste n''a pas participé à son activation.', 'LES VERSIONS DU RAPPORT', 'Une copie du programme indique qu’un effet de scène a été autorisé tard. L’expertise le relie à l’incendie.'),
('020', 'C', 'v600_runtime_trames', '6', 'DEUX CHRONOLOGIES À RECROISER', 'Le journal de réception, l''avis technique urgent et les communications d''ordre montrent que la coordination a différé l''annonce générale pour maintenir le passage d''une délégation VIP. Ce choix suit la compréhension du danger.', 'ALARME RETARDÉE POUR LES VIP', 'Des messages montrent que l’alarme a été repoussée pendant le passage d’une délégation VIP.')
), revised_fields AS (
 SELECT m.scenario_id,m.variant_id,k.key,
  jsonb_agg(CASE WHEN ed.scenario_id IS NOT NULL
   THEN jsonb_set(jsonb_set(t.item,'{text}',to_jsonb(ed.new_text),true),'{title}',to_jsonb(ed.new_title),true)
   ELSE t.item END ORDER BY t.ord) updated_array,
  count(ed.scenario_id) matched
 FROM igr_private.igr_v99_room_canons m
 CROSS JOIN LATERAL jsonb_each(m.manuscript) k(key,payload)
 CROSS JOIN LATERAL jsonb_array_elements(
  CASE WHEN k.key ~ '_runtime_trames$' AND jsonb_typeof(k.payload)='array' THEN k.payload ELSE '[]'::jsonb END
 ) WITH ORDINALITY t(item,ord)
 LEFT JOIN edits ed ON ed.scenario_id=m.scenario_id AND ed.variant_id=m.variant_id AND
 ed.field=k.key AND ed.ord=t.ord AND ed.old_title=t.item->>'title' AND ed.old_text=t.item->>'text'
 WHERE m.scenario_id BETWEEN '001' AND '020' AND k.key~'_runtime_trames$'
 GROUP BY m.scenario_id,m.variant_id,k.key
), revised_manuscripts AS (
 SELECT scenario_id,variant_id,jsonb_object_agg(key,updated_array) new_fields,sum(matched) changed_count
 FROM revised_fields GROUP BY scenario_id,variant_id
), ready AS (
 SELECT m.scenario_id,m.variant_id,b.changed_count,(m.manuscript||b.new_fields) new_manuscript
 FROM igr_private.igr_v99_room_canons m JOIN revised_manuscripts b
 ON b.scenario_id=m.scenario_id AND b.variant_id=m.variant_id
 WHERE b.changed_count>0
)
UPDATE igr_private.igr_v99_room_canons m SET manuscript=r.new_manuscript,
 manuscript_md5=md5(r.new_manuscript::text)
FROM ready r WHERE m.scenario_id=r.scenario_id AND m.variant_id=r.variant_id
RETURNING m.scenario_id,m.variant_id,r.changed_count;
